import {ITEMS} from './data.js';
import {manualBattleBody} from './kolom-jrpg.js';
import {heroAttributes,effectiveMaxHp} from './game.js';
import {paoloCandidates} from './paolo-route.js';
export function paoloBody(s,{btn,esc,health,heroPortrait}){
 const t=s.paoloTrial,b=(label,choice)=>btn(label,'paoloChoice','data-choice="'+choice+'"','full secondary');
 const intro='<p class="note">Тестовая встреча: последствия действуют только внутри сцены. На последнем экране — сводка; после закрытия восстановится исходное сохранение, следующий вызов через 5 минут.</p>';
 const art=phase=>'<img class="interactive-stage-image" src="./paolo-scenes/'+phase+'.jpg" alt="Паоло и трое бойцов Синих на Автозаводской">';
 if(t.phase==='prepare')return intro+'<h3>Собраться для встречи</h3><p>Выберите 1–3 живых героев, включая хотя бы одного отмеченного. Незавершённые попытки прервутся без результата и урона; завершённые результаты соберутся во временные ячейки при нехватке места.</p>'+paoloCandidates(s).map(h=>{const a=heroAttributes(h);return '<label class="card paolo-hero-choice"><span class="row"><input type="checkbox" data-paolo-hero="'+esc(h.id)+'" '+(t.selected.includes(h.id)?'checked':'')+'><span class="portrait small hero-portrait">'+heroPortrait(h)+'</span><strong>'+esc(h.name)+' · ур. '+h.level+(h.mark?' · С МЕТКОЙ':'')+'</strong></span>'+health(h)+'<small>СИЛ '+a.strength+' · ЛОВ '+a.agility+' · ИНТ '+a.intelligence+' · ВОС '+a.perception+'</small><p class="subtitle">'+(h.job?'Занят: поход будет прерван':'Свободен')+'</p></label>';}).join('')+btn('Выбрать героев, завершить походы и собраться вместе','gatherPaoloTrial','','full mission-start');
 if(t.phase==='victory')return '<div class="paolo-victory-stage">'+manualBattleBody(s.interactiveMission,s.heroes)+(t.victoryReady?'<div class="paolo-victory-overlay"><h2>Победа</h2><p>Вы обезоруживаете нападавших и приводите их в чувство для допроса. Паоло доставляют в отдельный кабинет.</p>'+b('Перейти к допросу','interrogate')+'</div>':'')+'</div>';
 if(t.phase==='combat')return manualBattleBody(s.interactiveMission,s.heroes)+(s.interactiveMission.combat.status==='casualty'?btn('Продолжить бой','paoloCombatContinue','','full danger'):'');
 if(t.phase==='result')return (['prison','deal'].includes(t.outcome)?'<div class="paolo-prison-preview"><img src="./paolo-scenes/portrait.jpg" alt="Паоло за решёткой"><span>Переговоры с Синими</span></div>':t.outcome==='passport'?'<div class="paolo-passport-preview">ПАСПОРТ СИНИХ<br><small>Следы крови · Переговоры с Синими</small></div>':'')+'<h3>Итоги встречи · тест</h3>'+(t.victoryRewardClaimed?'<p class="note gold">Опыт на отряд: '+t.rewardXp+' XP · найдено '+(t.rewardMoney/10)+' А</p><h3>Добыча</h3><ul>'+t.rewardItems.map(row=>'<li>'+esc(ITEMS[row.item]?.name??row.item)+(row.quality?' +'+row.quality:'')+' ×'+row.qty+(row.charges!=null?' · '+row.charges+' применений':'')+'</li>').join('')+'</ul><h3>Опыт героев</h3>'+Object.entries(t.rewardGains).map(([id,xp])=>'<p>'+esc(s.heroes.find(h=>h.id===id)?.name??id)+' · +'+xp+' XP</p>').join(''):'')+'<ul>'+t.summary.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul>'+(s.interactiveMission.combat?'<h3>Участники</h3>'+s.interactiveMission.combat.heroes.map(h=>'<p>'+esc(h.name)+' · HP '+Math.max(0,Math.round(h.hp))+' / '+Math.round(h.maxHp??h.hp)+'</p>').join(''):'')+'<details class="battle-log result-log"><summary>Разговор и проверки</summary>'+t.events.map(text=>'<p>'+esc(text)+'</p>').join('')+'</details><p class="warning">Это тест: плен, договор, ранения, расход предметов и изменения походов не сохраняются в основной игре.</p>'+btn('Завершить тест · повтор через 5 минут','finishPaoloTrial','','full expedition-result-return');
 if(t.phase==='confirm')return art('talk')+'<p class="warning">Паоло заберёт отмеченного героя вместе со снаряжением. Станция заключит договор с Синими и будет действовать под их контролем.</p>'+b('Подчиниться и пройти с Паоло','submit')+b('Вернуться к разговору','back');
 if(t.phase==='talk')return art('talk')+'<h3>Паоло · Синие</h3><p>«Ваш отмеченный идёт с нами. Автозаводская присоединится к Синим. Подчинитесь и проследуйте за мной».</p>'+b('Согласиться · последствия договора','agree')+b('Отказать. Мы никуда не идём','refuse');
 if(t.phase==='shooting')return art('shooting')+'<p>Бойцы вскидывают оружие. Их главная цель — герой с меткой.</p>'+b('Начать бой','fight');
 const survivors=s.interactiveMission.combat.heroes.filter(h=>h.hp>0&&!h.dead);
 return art('interrogation')+'<h3>Допрос Паоло · раунд '+Math.min(3,(t.questions??0)+1)+' / 3</h3><label>Кто ведёт допрос</label><select id="paolo-speaker" class="hero-select">'+survivors.map(f=>{const h=s.heroes.find(h=>h.id===f.id);return '<option value="'+esc(h.id)+'">'+esc(h.name)+' · ВОС '+heroAttributes(h).perception+'</option>';}).join('')+'</select><div class="battle-log result-log" aria-live="polite">'+t.events.slice(-8).map(text=>'<p>'+esc(text)+'</p>').join('')+'</div>'+((t.step??0)<2&&(t.implantAlarm??0)<3?b('Продолжить расспросы · ВОС против '+[12,15,18][t.implantAlarm??0],'question'):b('Предложить сделку · ВОС 18','deal')+b('Жёстко надавить · ВОС 22','pressure'))+(t.implantWarning?'<p class="warning">Имплант активируется. Продолжение убьёт Паоло.</p>'+b('Продолжить давление, несмотря на риск','continuePressure'):'')+b('Закончить допрос · оставить под стражей','jail');
}
